/*
 * A226463  Triangle read by rows giving successive states of cellular
 *          automaton generated by "Rule 135" within range n from the origin.
 * https://oeis.org/A226463
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabf
 * Formula:   not stated
 * Range:     u8 n <= 9264, u16 n <= 9264, u32 n <= 9264, u64 n <= 9264,
 *            u128 n <= 9264, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* a(n) = cell value at row r = floor(sqrt(n)) in the Rule‑135 1‑D cellular automaton.
   Each row r contains 2r+1 cells; the sequence is obtained by reading all rows
   consecutively, with all cells outside the displayed range assumed to be 1. */

#include <stdlib.h>
#include <stdint.h>

static const unsigned char rule135[8] = {1, 1, 1, 0, 0, 0, 0, 1};

seq_t a(idx_t n)
{
    /* Find the row (r) that contains position n and the offset within that row. */
    idx_t r = 0;
    while ((r + 1) * (r + 1) <= n)
        ++r;
    idx_t offset = n - r * r;

    /* Generate rows up to r.  Row r has length 2r+1. */
    unsigned char *prev = (unsigned char *)malloc(1);
    prev[0] = 0;                    /* Row 0: single cell with value 0 */
    idx_t prev_len = 1;

    if (r == 0) {
        seq_t result = (seq_t)prev[0];
        free(prev);
        return result;
    }

    unsigned char *cur = NULL;
    for (idx_t row = 1; row <= r; ++row) {
        idx_t cur_len = prev_len + 2;
        cur = (unsigned char *)malloc(cur_len);
        for (idx_t j = 0; j < cur_len; ++j) {
            unsigned char l  = (j >= 2)               ? prev[j - 2] : 1;
            unsigned char m  = (j >= 1 && j - 1 < prev_len) ? prev[j - 1] : 1;
            unsigned char rr = (j < prev_len)        ? prev[j] : 1;

            unsigned char key = (l << 2) | (m << 1) | rr;
            cur[j] = rule135[key];
        }
        free(prev);
        prev = cur;
        prev_len = cur_len;
    }

    seq_t result = (seq_t)prev[offset];
    free(prev);
    return result;
}
